import {
  GenerationJobCreateRequestSchema,
  WorkerCompleteRequestSchema,
} from '@chordflow/chart-schema';
import { parseChord } from '@chordflow/music-theory';
import { describe, expect, it } from 'vitest';
import golden from '../../../../../fixtures/contracts/worker/mock-complete.golden.json';
import createRequest from '../../../../../fixtures/contracts/worker/job-create-request.json';
import type { JobRow } from './views';
import { validateCompletion } from './worker-service';

/**
 * The Python mock chain's output (regenerated by `UPDATE_GOLDEN=1 pytest`)
 * must pass the exact validation the server runs on completion.
 */
describe('Python mock worker output', () => {
  const request = WorkerCompleteRequestSchema.parse(golden);
  // validateCompletion reads only the job id and the stored request.
  const row = {
    id: 'job_fixture_001',
    request: GenerationJobCreateRequestSchema.parse(createRequest),
  } as JobRow;

  it('passes the server completion checks', () => {
    expect(validateCompletion(row, request)).toEqual([]);
  });

  it('uses chord symbols the music-theory engine understands', () => {
    const symbols = request.draft.document.sections.flatMap((s) =>
      s.lines.flatMap((l) => l.chords.map((c) => c.symbol)),
    );
    expect(symbols.length).toBeGreaterThan(5);
    for (const symbol of symbols) expect(parseChord(symbol).ok, symbol).toBe(true);
  });
});
